class Solution {
public:
    string licenseKeyFormatting(string s, int k) {
        string result;
        int count = 0;
        for (int i = (int)s.size() - 1; i >= 0; i--) {
            char c = s[i];
            if (c == '-') continue;
            if (count > 0 && count % k == 0) {
                result.push_back('-');
            }
            if (c >= 'a' && c <= 'z') c -= 32;
            result.push_back(c);
            count++;
        }
        reverse(result.begin(), result.end());
        return result;
    }
};
